<style>.section-label{color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.3em;text-transform:uppercase}.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.event-card{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--border);border-radius:26px;background:#fff;transition:.4s var(--ease)}.event-card:hover{transform:translateY(-5px);border-color:var(--primary);box-shadow:var(--shadow-elegant)}.event-card img{width:100%;height:220px;object-fit:cover}.event-info{display:flex;flex:1;flex-direction:column;padding:24px}.event-info h2{margin:8px 0;font-size:22px}.event-meta{color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.event-info p{color:var(--muted-foreground);font-size:14px}.event-more{margin-top:auto;color:var(--primary-deep);font-weight:700}.cat-cta{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-top:42px;padding:30px;border-radius:26px;background:var(--gradient-cool)}.empty-campus{grid-column:1/-1;padding:30px;border:1px solid var(--border);border-radius:22px;background:var(--muted);color:var(--muted-foreground)}@media(max-width:900px){.event-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.event-grid{grid-template-columns:1fr}.cat-cta{align-items:flex-start;flex-direction:column}}</style>
<section class="hero"><div class="wrap"><div class="crumbs"><a href="/idemaclima/">Home</a> / Campus</div><span class="section-label">Formazione e incontri</span><h1>Campus IDEMA</h1><p>Eventi, incontri tecnici e appuntamenti formativi aperti al pubblico.</p></div></section>
<section class="content"><div class="wrap"><div class="event-grid"><?php foreach($events as $event): ?><a class="event-card" href="/idemaclima/campus/<?= e($event['slug']) ?>"><?php if(!empty($event['cover_image'])):?><img src="<?= e($event['cover_image']) ?>" alt="<?= e($event['title']) ?>"><?php endif; ?><div class="event-info"><span class="event-meta"><?= e(date('d/m/Y H:i',strtotime((string)$event['starts_at']))) ?><?= !empty($event['location'])?' · '.e($event['location']):'' ?></span><h2><?= e($event['title']) ?></h2><?php if(!empty($event['short_description'])):?><p><?= e($event['short_description']) ?></p><?php endif; ?><span class="event-more">Scopri l’evento →</span></div></a><?php endforeach; ?><?php if(!$events): ?><div class="empty-campus">Nessun evento pubblico in programma.</div><?php endif; ?></div><div class="cat-cta"><div><span class="section-label">Centri assistenza tecnica</span><h2>Area riservata CAT</h2><p>Accedi agli incontri e ai contenuti dedicati alla rete di assistenza IDEMA.</p></div><a class="btn" href="/idemaclima/campus/cat">Accedi all’Area CAT</a></div></div></section>
